/** C ref: sounds.c:546 — @param {CPtr<struct monst>} mon @returns {CPtr<char>} */
export function maybe_gasp(mon) {
    let mptr = cptr.ldPtro(mon, $monst_data);
    let msound = cptr.ld1uo(mptr, $permonst_msound);
    let dogasp = 0;

    /* other roles' guardians and cross-aligned priests don't gasp */
    if ((msound == NHC.MS_GUARDIAN &&
        !cptr.eq(
            mptr,
            cptr.add(
                mons,
                cptr.ldI16o(gu, $instance_globals_u_urole + $Role_guardnum),
                $sizeof_permonst
            )
        )) ||
            (msound == NHC.MS_PRIEST && !p_coaligned(mon)))
        msound = NHC.MS_SILENT;
    else if (msound == NHC.MS_CUSS &&
            has_emin(mon) &&
            (p_coaligned(mon)
                ? !cptr.ld1so(
                    (cptr.ldPtro(cptr.ldPtro((mon), $monst_mextra), $mextra_emin)),
                    $emin_renegade
                )
                : cptr.ld1so(
                    (cptr.ldPtro(cptr.ldPtro((mon), $monst_mextra), $mextra_emin)),
                    $emin_renegade
                )))
        msound = NHC.MS_HUMANOID;

    /*
     * Only called for humanoids so animal noise handling is ignored.
     */
    switch (msound) {
        case NHC.MS_HUMANOID:
        case NHC.MS_ARREST:
        case NHC.MS_SOLDIER:
        case NHC.MS_GUARD:
        case NHC.MS_NURSE:
        case NHC.MS_SEDUCE:
        case NHC.MS_LEADER:
        case NHC.MS_GUARDIAN:
        case NHC.MS_SELL:
        case NHC.MS_ORACLE:
        case NHC.MS_PRIEST:
        case NHC.MS_BOAST:
        case NHC.MS_IMITATE:
        dogasp = 1;
        break;
        case NHC.MS_ORC:
        case NHC.MS_GRUNT:
        case NHC.MS_LAUGH:
        case NHC.MS_ROAR:
        case NHC.MS_BELLOW:
        case NHC.MS_DJINNI:
        case NHC.MS_VAMPIRE:
        case NHC.MS_WERE:
        case NHC.MS_SPELL:
        dogasp = schar((cptr.ld1so(mptr, $permonst_mlet) ==
                cptr.ld1so(
                    cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
                    $permonst_mlet
                )));
        break;
        case NHC.MS_BRIBE:
        case NHC.MS_CUSS:
        case NHC.MS_RIDER:
        case NHC.MS_NEMESIS:
        case NHC.MS_SILENT:
        default:
        break;
    }
    if (dogasp) {
        return cptr.ldPtro(__static_maybe_gasp_Exclam, rn2(5), 8);  /* [mon->m_id % SIZE(Exclam)]; */
    }
    return null;
}

